local PoolManager   = CS.Engine.Lib.PoolManager
local CDTimerModule = CS.Engine.Modules.CDTimerModule

local POOL_MAX = 0

--- from: Assets/BundleResources/Prefabs/Common/CommonTipsPanel.prefab
---@class UIAutoTips
---@field Env                           	UIAutoTips                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field Root                          	UnityEngine.RectTransform               
---@field ContentText                   	UnityEngine.UI.Text                     
local UIAutoTips = Class('UIAutoTips')


function UIAutoTips:__init()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end


function UIAutoTips:__delete()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end


function UIAutoTips:Awake()
    self.controller.ClearCache = false
    -- reset view
    self.ContentText.text = ''
    -- reset anim
    CfUtils.PlayAnimator(self.controller, 'CommonTipsPanel')
end


--- 显示一tips的方法调用
---@param textTip string 显示内容
---@param rTimeLength number 显示时长
function UIAutoTips:ShowHUD(textTip, rTimeLength)
    self.ContentText.text = textTip

    local closeInterval = checkInt(rTimeLength)
    self.closeTimer_ = CDTimerModule.GetInstance():AddCD(closeInterval, function(i, t)
        if not isNull(self) and not isNull(self.controller) then
            PoolManager.Instance:GiveBack(self.controller.gameObject, POOL_MAX)
        end
    end)
    
    local exitAnimTime  = CfUtils.GetAnimatorTime(self.controller, 'CommonTipsPanelExit')
    local doAnimIntaval = math.floor(math.max(closeInterval - exitAnimTime, 0))  -- cd 只能是 int 值，所以只能小数部分社区，提早播放动画
    self.animeTimer_ = CDTimerModule.GetInstance():AddCD(doAnimIntaval, function(i, t)
        if not isNull(self) and not isNull(self.controller) then
            CfUtils.PlayAnimator(self.controller, 'CommonTipsPanelExit')
        end
    end)
end


function UIAutoTips:OnDestroy()
    ---加回到对象池中去
    if not isNull(self.closeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.closeTimer_)
        self.closeTimer_ = nil
    end
    if not isNull(self.animeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.animeTimer_)
        self.animeTimer_ = nil
    end
    self:Delete()
    self.controller = nil--luabehaviour 中CSharp对象
    self = nil
end


return UIAutoTips
